"use client";

import { loadFont } from "@remotion/google-fonts/InstrumentSans";
import type React from "react";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import {
  type ResolvedElement,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import {
  DEFAULT_START,
  DEFAULT_STEPS,
  shownSteps,
  type WaterfallChartElementId,
  waterfallChartTimeline,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

// gradients.sh "mesh" palette (bg #0a0d24): #ecdcf2, #8796ee, #2e45b7, #0e1645.
const MESH = ["#ecdcf2", "#8796ee", "#2e45b7", "#0e1645"] as const;

/** Mesh layers sized for a tall bar: soft wide blobs over a vertical ramp. */
function mesh(drift: number, base: string) {
  return [
    `radial-gradient(130% 34% at ${28 + 14 * drift}% 6%, ${MESH[0]} 0%, transparent 72%)`,
    `radial-gradient(150% 40% at ${74 - 10 * drift}% 34%, color-mix(in oklab, ${MESH[1]} 70%, transparent) 0%, transparent 70%)`,
    `radial-gradient(160% 46% at ${30 + 12 * drift}% 86%, color-mix(in oklab, ${MESH[2]} 80%, transparent) 0%, transparent 72%)`,
    base,
  ].join(", ");
}

export interface WaterfallStep {
  label: string;
  value: number;
}

export interface WaterfallChartProps {
  start?: WaterfallStep;
  steps?: WaterfallStep[];
  totalLabel?: string;
  title?: string;
  format?: (value: number) => string;
  accent?: string;
  /** Text color of the values and total label; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Frames each step bar takes to grow. */
  grow?: number;
  /** Corner radius of the bars, in px at 720p. */
  radius?: number;
  grain?: boolean;
  /** Size of the chart, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the axis, the title, each bar, the total and
   * the camera, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<WaterfallChartElementId>;
}

const defaultFormat = (v: number) => `$${Math.round(v)}k`;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_BAR = Easing.bezier(0.3, 0, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    axis: "rgba(255,255,255,0.2)",
    hair: "rgba(255,255,255,0.32)",
    base: "#6A696F",
    up: "#C9C7C2",
    down: "#2E2D33",
    downEdge: "rgba(255,255,255,0.16)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    axis: "rgba(18,18,20,0.2)",
    hair: "rgba(18,18,20,0.32)",
    base: "#9C9A95",
    up: "#3F3E3B",
    down: "#E3E1DB",
    downEdge: "rgba(18,18,20,0.24)",
    grain: 0.045,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={41}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

interface Column {
  key: string;
  label: string;
  kind: "start" | "up" | "down" | "total";
  from: number;
  to: number;
  delta: number;
  el: ResolvedElement<WaterfallChartElementId>;
}

export function WaterfallChart(props: WaterfallChartProps) {
  const {
    start = DEFAULT_START,
    steps = DEFAULT_STEPS,
    totalLabel = "MRR",
    title = "Net revenue, Q3",
    format = defaultFormat,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    radius: corner = 2,
    grain = true,
    scale: zoom = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    waterfallChartTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const u = Math.min(width / 1280, height / 720);
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? p.bg);
  const list = shownSteps(steps);

  const cols: Column[] = [];
  cols.push({
    key: "start",
    label: start.label,
    kind: "start",
    from: 0,
    to: start.value,
    delta: start.value,
    el: tl.get("base"),
  });
  let level = start.value;
  list.forEach((s, i) => {
    const next = level + s.value;
    cols.push({
      key: `s${i}`,
      label: s.label,
      kind: s.value < 0 ? "down" : "up",
      from: level,
      to: next,
      delta: s.value,
      el: tl.get(`step:${i}`),
    });
    level = next;
  });
  const total = level;
  const totalEl = tl.get("total");
  const TOTAL_AT = totalEl.start;
  cols.push({
    key: "total",
    label: totalLabel,
    kind: "total",
    from: 0,
    to: total,
    delta: total,
    el: totalEl,
  });

  const maxLevel = Math.max(
    1,
    ...cols.map((c) => Math.max(c.from, c.to)),
    total,
  );

  const plotL = width * 0.1;
  const plotR = width * 0.9;
  const baseY = height * 0.82;
  const topY = height * 0.34;
  const yOf = (v: number) => baseY - ((baseY - topY) * v) / maxLevel;
  const slot = (plotR - plotL) / cols.length;
  const colW = Math.min(slot * 0.58, 92 * u);
  const xOf = (i: number) => plotL + slot * (i + 0.5);

  const axisEl = tl.get("axis");
  const titleEl = tl.get("title");
  const pushEl = tl.get("push");
  const settleEl = tl.get("settle");
  const focusEl = tl.get("focus");
  const driftEl = tl.get("drift");
  const axisIn = interpolate(t, [axisEl.start, axisEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const titleIn = interpolate(t, [titleEl.start, titleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const totalRise = spring({
    frame: t - TOTAL_AT,
    fps,
    config: { damping: 15, stiffness: 120, mass: 0.8 },
  });
  const count = interpolate(
    t,
    [TOTAL_AT, TOTAL_AT + totalEl.beat("count")],
    [0, 1],
    {
      ...CLAMP,
      easing: Easing.bezier(0.22, 1, 0.36, 1),
    },
  );
  const land = interpolate(
    t,
    [TOTAL_AT + totalEl.beat("landAt"), TOTAL_AT + totalEl.beat("landEnd")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const unitIn = interpolate(
    t,
    [TOTAL_AT + totalEl.beat("unitAt"), TOTAL_AT + totalEl.beat("unitEnd")],
    [0, 1],
    { ...CLAMP, easing: EASE_OUT },
  );
  const focus = interpolate(t, [focusEl.start, focusEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const push = interpolate(t, [pushEl.start, pushEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const scale = 0.975 + 0.025 * push;
  const settle = interpolate(t, [settleEl.start, settleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const shift = (1 - settle) * -0.075 * height;

  const progress = (c: Column) =>
    c.kind === "total"
      ? Math.max(0, totalRise)
      : interpolate(t, [c.el.start, c.el.end], [0, 1], {
          ...CLAMP,
          easing: EASE_BAR,
        });

  const sw = Math.max(1, u);
  const radius = corner * u;
  const totalK = Math.max(0, totalRise);
  const barFull = baseY - yOf(total);
  const drift = interpolate(t, [driftEl.start, driftEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const barBase = `linear-gradient(180deg, ${MESH[0]} 0%, ${MESH[1]} 34%, ${MESH[2]} 82%, #283da6 100%)`;
  const labelSize = 16 * u;
  const valueSize = 17 * u;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={zoom}>
        <AbsoluteFill
          style={{
            // The push outlasts every move inside it, so this one tilt covers
            // all the text in the chart.
            transform: `scale(${scale})${glide(midway(push))}`,
            transformOrigin: "50% 55%",
          }}
        >
          <AbsoluteFill style={{ transform: `translateY(${shift}px)` }}>
            <svg
              width={width}
              height={height}
              style={{ position: "absolute", inset: 0 }}
              aria-hidden
            >
              <line
                x1={plotL}
                x2={plotL + (plotR - plotL) * axisIn}
                y1={baseY + sw / 2}
                y2={baseY + sw / 2}
                stroke={p.axis}
                strokeWidth={sw}
              />
              {cols.map((c, i) => {
                if (i === 0) return null;
                const prev = cols[i - 1];
                const y = yOf(prev.to);
                const x0 = xOf(i - 1) + colW / 2;
                const x1 = xOf(i) - colW / 2;
                const k = interpolate(
                  t,
                  [
                    c.el.start + c.el.beat("connect"),
                    c.el.start + c.el.beat("connectEnd"),
                  ],
                  [0, 1],
                  { ...CLAMP, easing: EASE_IO },
                );
                if (k <= 0) return null;
                const dim = c.kind === "total" ? 1 : 1 - 0.45 * focus;
                return (
                  <line
                    key={`c${c.key}`}
                    x1={x0}
                    x2={x0 + (x1 - x0) * k}
                    y1={y}
                    y2={y}
                    stroke={p.hair}
                    strokeWidth={sw}
                    opacity={dim}
                  />
                );
              })}
              {cols.map((c, i) => {
                const k = progress(c);
                if (k <= 0 || c.kind === "total") return null;
                const anchor = c.from;
                const end = anchor + (c.to - anchor) * k;
                const lo = Math.min(anchor, end);
                const hi = Math.max(anchor, end);
                const y0 = yOf(hi);
                const h = Math.max(sw, yOf(lo) - y0);
                const fill =
                  c.kind === "start" ? p.base : c.kind === "up" ? p.up : p.down;
                const op = 1 - 0.4 * focus;
                return (
                  <rect
                    key={c.key}
                    x={xOf(i) - colW / 2}
                    y={y0}
                    width={colW}
                    height={h}
                    rx={radius}
                    fill={fill}
                    stroke={c.kind === "down" ? p.downEdge : "none"}
                    strokeWidth={c.kind === "down" ? sw : 0}
                    opacity={op}
                  />
                );
              })}
            </svg>

            {totalK > 0 ? (
              <div
                style={{
                  position: "absolute",
                  left: xOf(cols.length - 1) - colW / 2,
                  top: yOf(total * totalK),
                  width: colW,
                  height: baseY - yOf(total * totalK),
                  borderRadius: radius,
                  overflow: "hidden",
                  background: MESH[0],
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    left: 0,
                    right: 0,
                    bottom: 0,
                    height: barFull,
                    background: mesh(drift, barBase),
                  }}
                />
              </div>
            ) : null}

            {cols.map((c, i) => {
              const a = interpolate(
                t,
                [c.el.start, c.el.start + c.el.beat("label")],
                [0, 1],
                { ...CLAMP, easing: EASE_OUT },
              );
              const dim = c.kind === "total" ? 1 : 1 - 0.35 * focus;
              return (
                <div
                  key={`l${c.key}`}
                  style={{
                    position: "absolute",
                    left: xOf(i),
                    top: baseY + 14 * u,
                    transform: `translate(-50%, ${(1 - a) * 6 * u}px)`,
                    fontFamily,
                    fontWeight: 400,
                    fontSize: labelSize,
                    color: c.kind === "total" ? fg : p.muted,
                    whiteSpace: "nowrap",
                    opacity: a * dim,
                  }}
                >
                  {c.label}
                </div>
              );
            })}

            {cols.map((c, i) => {
              if (c.kind === "total") return null;
              const a = interpolate(
                t,
                [
                  c.el.end + c.el.beat("valueIn"),
                  c.el.end + c.el.beat("valueEnd"),
                ],
                [0, 1],
                { ...CLAMP, easing: EASE_OUT },
              );
              const top = yOf(Math.max(c.from, c.to));
              const text =
                c.kind === "start"
                  ? format(c.delta)
                  : `${c.delta < 0 ? "−" : "+"}${format(Math.abs(c.delta))}`;
              return (
                <div
                  key={`v${c.key}`}
                  style={{
                    position: "absolute",
                    left: xOf(i),
                    top: top - 10 * u,
                    transform: `translate(-50%, ${-100 + (1 - a) * 18}%)`,
                    fontFamily,
                    fontWeight: 500,
                    fontSize: valueSize,
                    letterSpacing: "-0.005em",
                    fontVariantNumeric: "tabular-nums",
                    color: c.kind === "down" ? p.muted : fg,
                    whiteSpace: "nowrap",
                    opacity: a * (1 - 0.4 * focus),
                  }}
                >
                  {text}
                </div>
              );
            })}

            <div
              style={{
                position: "absolute",
                left: plotL,
                top: height * 0.255,
                transform: `translateY(-100%) translateY(${(1 - titleIn) * 8 * u}px)`,
                fontFamily,
                fontWeight: 400,
                fontSize: 20 * u,
                letterSpacing: "-0.01em",
                color: p.muted,
                whiteSpace: "nowrap",
                opacity: titleIn,
              }}
            >
              {title}
            </div>
          </AbsoluteFill>

          <div
            style={{
              position: "absolute",
              right: width - plotR,
              top: height * 0.255,
              transform: "translateY(-100%)",
              display: "flex",
              alignItems: "baseline",
              gap: 14 * u,
              whiteSpace: "nowrap",
            }}
          >
            <span
              style={{
                fontFamily,
                fontWeight: 400,
                fontSize: 136 * u,
                lineHeight: 0.86,
                letterSpacing: "-0.045em",
                paddingRight: "0.05em",
                color: "transparent",
                backgroundImage: `linear-gradient(100deg, ${theme === "dark" ? MESH[0] : MESH[2]} ${4 + 10 * drift}%, ${MESH[1]} 48%, ${theme === "dark" ? MESH[2] : MESH[3]} 100%)`,
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                fontVariantNumeric: "tabular-nums",
                display: "inline-block",
                opacity: land,
                filter:
                  land < 0.99 ? `blur(${(1 - land) * 8 * u}px)` : undefined,
                transform: `translateY(${(1 - land) * 20 * u}px)`,
              }}
            >
              {format(total * count)}
            </span>
            <span
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 10 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 30 * u,
                letterSpacing: "-0.015em",
                color: p.muted,
                opacity: unitIn,
                transform: `translateY(${(1 - unitIn) * 8 * u}px)`,
              }}
            >
              <span
                style={{
                  width: 10 * u,
                  height: 10 * u,
                  borderRadius: "50%",
                  background: accent,
                }}
              />
              {totalLabel}
            </span>
          </div>
        </AbsoluteFill>
      </ScaleLayer>

      {transparent ? null : (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${stage} 100%)`,
            opacity: 0.5,
          }}
        />
      )}
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The axis and title fading in, the starting bar growing, each step bar
// growing from the level the one before left, and the total: its bar
// springing up, the figure counting to it, the rest of the chart dimming.
// The camera pushes in and lifts the chart as the total arrives. Frames on
// the 30 fps scene timeline, after `delay` and `speed`. The ids are public:
// a saved `timing` prop refers to them.

export type WaterfallChartElementId =
  | "push"
  | "drift"
  | "axis"
  | "title"
  | "base"
  | `step:${number}`
  | "settle"
  | "total"
  | "focus";

interface Step {
  label: string;
  value: number;
}

export interface WaterfallChartTimingProps {
  start?: Step;
  steps?: Step[];
  totalLabel?: string;
  grow?: number;
}

export const DEFAULT_START: Step = { label: "Start", value: 52 };

export const DEFAULT_STEPS: Step[] = [
  { label: "Churn", value: -7 },
  { label: "Contraction", value: -3 },
  { label: "New", value: 24 },
  { label: "Expansion", value: 12 },
  { label: "Reactivation", value: 6 },
];

/** The steps the chart shows: the first eight. */
export function shownSteps(steps: Step[]) {
  return steps.slice(0, 8);
}

/** Beats every column has: its connector, from the column before, and label. */
const COLUMN = { connect: -7, connectEnd: 1, label: 14 };

// A column (`base`, `step:<i>`, `total`) grows over its length; the
// connector from the column before draws from `connect` to `connectEnd` and
// the label rises over `label`. A bar's value rises from `valueIn` to
// `valueEnd`, counted from the bar's END. The steps are a chain after
// `base`. `total` springs its bar up, counts the figure over `count`, lands
// it from `landAt` to `landEnd` and its unit from `unitAt` to `unitEnd`.
// `settle` lifts the chart and `focus` dims all but the total.
export const waterfallChartTimeline = defineTimeline<
  WaterfallChartElementId,
  WaterfallChartTimingProps
>(
  ({
    start = DEFAULT_START,
    steps = DEFAULT_STEPS,
    totalLabel = "MRR",
    grow = 15,
  }) => {
    const list = shownSteps(steps);
    const STAGGER = list.length > 5 ? 7 : 9;
    const TOTAL_AT = 26 + list.length * STAGGER + 6;
    const bar = { ...COLUMN, valueIn: -8, valueEnd: 6 };
    const last: WaterfallChartElementId =
      list.length > 0 ? `step:${list.length - 1}` : "base";
    // The settle starts before the last step when steps are close together;
    // it follows the latest bar already under way.
    let before = -1;
    list.forEach((_, i) => {
      if (26 + i * STAGGER <= TOTAL_AT - 14) before = i;
    });
    const settleAfter: WaterfallChartElementId =
      before >= 0 ? `step:${before}` : "base";
    const elements: TimelineElement<WaterfallChartElementId>[] = [
      {
        id: "push",
        lane: "Camera",
        label: "Push",
        start: 0,
        length: TOTAL_AT + 60,
      },
      {
        id: "drift",
        lane: "Colour",
        label: "Drift",
        start: 0,
        length: TOTAL_AT + 70,
      },
      { id: "axis", lane: "Axis", label: "Axis", start: 0, length: 18 },
      { id: "title", lane: "Title", label: "Title", start: 4, length: 18 },
      {
        id: "base",
        lane: "Bars",
        label: start.label,
        start: 8,
        length: 22,
        beats: bar,
      },
      ...list.map(
        (s, i): TimelineElement<WaterfallChartElementId> => ({
          id: `step:${i}`,
          lane: "Bars",
          label: s.label,
          start: 26 + i * STAGGER,
          length: grow,
          follows: i > 0 ? `step:${i - 1}` : "base",
          beats: bar,
        }),
      ),
      {
        id: "settle",
        lane: "Camera",
        label: "Settle",
        start: TOTAL_AT - 14,
        length: 36,
        follows: settleAfter,
      },
      {
        id: "total",
        lane: "Bars",
        label: totalLabel,
        start: TOTAL_AT,
        length: 26,
        follows: last,
        beats: {
          ...COLUMN,
          count: 24,
          landAt: 2,
          landEnd: 22,
          unitAt: 12,
          unitEnd: 30,
        },
      },
      {
        id: "focus",
        lane: "Focus",
        label: "Focus",
        start: TOTAL_AT + 14,
        length: 20,
        follows: "total",
      },
    ];
    return elements.sort((a, b) => a.start - b.start);
  },
);
